-- Tables the live worker already has from the docs repo at 8089647.
-- This fixture is for the HTTP behavior test. It is not a new migration:
-- live D1 already applied 0004, 0005, 0006, 0007, and the requester_gate
-- statement from 0010. Do not execute this file with wrangler against a remote database.
CREATE TABLE oauth_clients (client_id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id), subject_kind TEXT NOT NULL CHECK(subject_kind IN ('agent','user')), redirect_uris_json TEXT NOT NULL, secret_hash TEXT NOT NULL, credential_version INTEGER NOT NULL CHECK(credential_version>0), scopes_json TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at INTEGER NOT NULL);
CREATE TABLE principal_bindings (issuer TEXT NOT NULL, subject TEXT NOT NULL, credential_id TEXT NOT NULL, principal_id TEXT NOT NULL REFERENCES principals(id), kind TEXT NOT NULL CHECK(kind IN ('agent','user')), agent_id TEXT, room_id TEXT NOT NULL REFERENCES rooms(id), audience TEXT NOT NULL, ingress_id TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), credential_version INTEGER NOT NULL CHECK(credential_version>0), not_before_ms INTEGER NOT NULL, expires_at_ms INTEGER NOT NULL, scopes_json TEXT NOT NULL, PRIMARY KEY(issuer,subject,credential_id));
CREATE TABLE oauth_codes (code_hash TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES oauth_clients(client_id), principal_id TEXT NOT NULL, redirect_uri TEXT NOT NULL, code_challenge TEXT NOT NULL, resource TEXT NOT NULL, scopes_json TEXT NOT NULL, approved_by TEXT NOT NULL, expires_at INTEGER NOT NULL, used_at INTEGER);
CREATE TABLE oauth_tokens (token_hash TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('access','refresh')), family_id TEXT NOT NULL, client_id TEXT NOT NULL REFERENCES oauth_clients(client_id), principal_id TEXT NOT NULL, credential_version INTEGER NOT NULL, aud TEXT NOT NULL, scopes_json TEXT NOT NULL, issued_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER, replaced_by TEXT);
CREATE INDEX oauth_tokens_family ON oauth_tokens(family_id);
CREATE TABLE auth_audit (id INTEGER PRIMARY KEY AUTOINCREMENT, request_id TEXT NOT NULL, action TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN ('allow','deny')), reason TEXT NOT NULL, principal_id TEXT, client_id TEXT, at INTEGER NOT NULL, scopes_json TEXT);
CREATE TABLE owner_gate (id TEXT PRIMARY KEY CHECK(id='owner'), failures INTEGER NOT NULL DEFAULT 0, window_start INTEGER NOT NULL, locked_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE requester_gate (key_hash TEXT PRIMARY KEY, failures INTEGER NOT NULL DEFAULT 0, window_start INTEGER NOT NULL, locked_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE consent_flows (flow_hash TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES oauth_clients(client_id), redirect_uri TEXT NOT NULL, code_challenge TEXT NOT NULL, expires_at INTEGER NOT NULL, used_at INTEGER, outcome TEXT CHECK(outcome IN ('approved','denied')));
CREATE INDEX consent_flows_expiry ON consent_flows(expires_at);
